export class ContactDraftPanel {
  contactCode: string = ''
  submitContact(): void {
    if (this.contactCode.trim().length === 0) {
      promptAction.showToast({ message: 'Enter a contact code' })
      return
    }
    this.dispatchContact(this.contactCode)
  }
  private dispatchContact(value: string): void {}
  refreshPreview(): void {}
}

